from lib import *
S = SS('w12')
steps = [
    step("在真实网口 en0(MTU 1500)上向网关的 9 号端口(discard)发一个 4000 字节的 UDP 数据报,加上 8 字节 UDP 头,IP 载荷是 4008 字节,抓到 3 个 IP 分片:三个分片的 id 都是 843;前两个 MF=1,最后一个 MF=0;片偏移 0、1480、2960;IP 总长 1500、1500、1068,IP 载荷 1480、1480、1048,以太网帧长 1514、1514、1082。每个分片的载荷是 8 的倍数(最后一个除外),1480 = 1500 − 20。只有第一个分片带 UDP 头,后面的分片只有 IP 头加数据,单看它们不知道是哪个端口,所以按端口过滤的防火墙遇到分片很头疼。netstat -s -p ip 里“发出的分片”这次 +3,和抓到的 3 个一致。", t=tl(S(1)), mark=lidx(S(1), '843     1   0   0', '843     1   0   1480', '843     0   0   2960'), done=lidx(S(1), '规律', '只有第一个分片带 UDP 头', 'netstat -s -p ip 的计数'), b=bars([['分片 1 IP 载荷', 1480, '1480'], ['分片 2 IP 载荷', 1480, '1480'], ['分片 3 IP 载荷', 1048, '1048']], 1480, mark=[2], done=[0, 1]), kv=KV([['标识 id', '3 个分片相同(843)'], ['MF', '1 / 1 / 0:最后一个为 0'], ['片偏移', '0 / 1480 / 2960 字节(字段单位 8 字节)'], ['UDP 头', '只在第一个分片里']], ['MF'])),
    step("环回接口上会分片吗?lo0 的 MTU 是 16384,先看系统限制:net.inet.udp.maxdgram 是 9216,不调大 SO_SNDBUF 直接发 20000 字节会报 [Errno 40] Message too long。调大发送缓冲区后 sendto(40000 字节)成功,一次 recvfrom 拿到 40000 字节,但 lo0 上只抓到 1 个 IP 包:IP 载荷 40008,MF=0,偏移 0——远大于 MTU 16384,却没有分片,macOS 的 lo0 不对超过 MTU 的包分片,整包交给本机的接收方。内核的被分片、发出的分片、收到的分片、成功重组这几个计数都是 +0。", t=tl(S(2)), mark=lidx(S(2), 'Message too long', '1 个 IP 包', '分片 1: id'), done=lidx(S(2), 'net.inet.udp.maxdgram', '内核计数'), kv=KV([['udp.maxdgram', '9216 字节'], ['40000 字节的 UDP', 'lo0 上 1 个 IP 包,不分片'], ['内核分片计数', '全部 +0']], ['40000 字节的 UDP'])),
    step("分片的代价之一是“丢一个全丢”。在 lo0 上用 netlab 造 5% 丢包,发 1000、20000、60000 字节的数据报各 1000 个:送达 953、949、950,约 95.3%、94.9%、95.0%,三档几乎一样——因为 60000 字节在 lo0 上也是 1 个 IP 包,没有真分片,看不出放大效应。要看放大效应,得有 MTU 1500 的路径;丢包只能在 lo0 上注入,所以下面用公式加随机模拟补上(这是计算,不是实测):按 MTU 1500 分片,1000/4000/20000/60000 字节分别是 1/3/14/41 个分片,每个分片丢 5%,整个数据报送达的理论概率 0.95^n 是 95.0%、85.7%、48.8%、12.2%,模拟 10 万次得 95.1%、85.6%、48.8%、12.2%。60000 字节的数据报在 5% 丢包的以太网路径上只有约八分之一能送到。", t=tl(S(3)), mark=lidx(S(3), '4000 字节     ', '20000 字节     ', '60000 字节     '), done=lidx(S(3), '1000 字节的数据报', '20000 字节的数据报', '60000 字节的数据报', '要看放大效应'), b=bars([['1000 字节 (1 片)', 95.0, '95.0%'], ['4000 字节 (3 片)', 85.7, '85.7%'], ['20000 字节 (14 片)', 48.8, '48.8%'], ['60000 字节 (41 片)', 12.2, '12.2%']], 100, mark=[2, 3], done=[0, 1]), kv=KV([['lo0 实测', '三档都约 95%(不分片)'], ['计算 0.95^n', '1 / 3 / 14 / 41 片 → 95.0 / 85.7 / 48.8 / 12.2%'], ['结论', '分片越多,整个数据报越难送达']], ['结论'])),
    step("TCP 避开分片的办法是 DF 位加 MSS:下载 1 MiB,在 lo0 上抓到 303 个 IP 包,MF 置位 0 个,片偏移非 0 的 0 个,DF 置位 302 个——TCP 的包基本都带 DF,不依赖分片;路径上放不下时靠 ICMP“需要分片但设置了 DF”告诉发送方调小(见 PMTUD 一篇)。", t=tl(S(4)), mark=lidx(S(4), '抓到 303'), done=lidx(S(4), '抓到 303'), b=bars([['IP 包总数', 303, '303'], ['DF 置位', 302, '302'], ['MF 置位 / 偏移非 0', 0, '0']], 303, mark=[1], done=[0]), kv=KV([['DF', '302 / 303 个包置位'], ['分片', '0 个']], ['DF'])),
    step("重组有成本和限制:net.inet.ip.maxfragpackets = 8192(同时在重组的包数上限),maxfragsperpacket = 128(一个包最多多少片)。netstat -s -p ip 此刻的计数:收到的分片 1716、成功重组的包 0、发出的分片 12、被分片的包 0、重组超时丢弃的分片 0、因其它原因丢弃的分片 0。这些计数没有哪项很大:现在流量以 TCP 为主,真正的 IP 分片已经少见。收到的分片是 1716 而成功重组是 0 这一点没有深入查原因。", t=tl(S(5)), mark=lidx(S(5), 'maxfragpackets', 'maxfragsperpacket'), done=lidx(S(5), 'netstat -s -p ip 当前计数', '这些计数多半'), kv=KV([['maxfragpackets', '8192'], ['maxfragsperpacket', '128'], ['收到的分片 / 成功重组', '1716 / 0'], ['发出的分片', '12']], ['maxfragpackets'])),
]
A = mkartw('w12', 12, '网络协议,IP分片,MF,片偏移,重组,DF,MTU,真实验证,动画演示',
    '在 en0(MTU 1500)上抓到 4000 字节 UDP 数据报被拆成 3 个同 id 分片(偏移 0/1480/2960,MF 1/1/0,只有第一片带 UDP 头);lo0 上 40000 字节不分片;按公式 5% 丢包下 41 片的数据报只有约 12% 能送达;TCP 下载 303 个包里 302 个带 DF。',
    'IP 包比链路的 MTU 大怎么办?拆成分片,到目的地再拼回去。但分片到底怎么标记、偏移怎么算、为什么说“丢一个全丢”、为什么 TCP 总是带 DF 位?这篇在真实网口上抓一个 4000 字节的 UDP 数据报,逐个分片看 id、MF、片偏移,再用实验和计算看分片的代价。',
    [('3 个分片', '4000 字节 UDP 数据报在 MTU 1500 的 en0 上:偏移 0 / 1480 / 2960,MF = 1 / 1 / 0'), ('12.2%', '计算值:5% 丢包下,60000 字节数据报(41 片)整个送达的概率,1000 字节的是 95.0%'), ('302 / 303', 'TCP 下载 1 MiB 时抓到的 IP 包里带 DF 位的个数,没有任何分片')],
    [('分片怎么标记', '<p>同一个数据报的所有分片共用一个 id;MF(更多分片)位除最后一个外都置 1;片偏移字段 13 位、单位是 8 字节,所以每个分片的载荷是 8 的倍数。实测 4000 字节 UDP 加 8 字节头,在 MTU 1500 上得到载荷 1480 / 1480 / 1048 的三个分片,只有第一个带 UDP 头。</p>'),
     ('环回不分片', '<p>macOS 的 lo0 MTU 是 16384,但 40000 字节的 UDP 数据报在 lo0 上仍是一个 IP 包,内核分片计数不动。想在本机看真分片,要用真实网口(如 en0)。</p>'),
     ('丢一个全丢', '<p>任何一个分片丢失,目的地就无法重组整个数据报。分片越多,送达概率按 0.95^n 下降。lo0 上的实测因为没有真分片,三档大小都约 95%;放大效应这部分是公式和模拟,不是实测。</p>'),
     ('TCP 的做法', '<p>TCP 的包带 DF 位,并用 MSS 限制段长,发送方根据 ICMP 的反馈调整,基本不依赖分片;实测 303 个包里 302 个带 DF,没有 MF 或非零偏移。</p>'),
     ('重组的限制', '<p>系统限制同时重组的包数和每个包的分片数(maxfragpackets、maxfragsperpacket),超时的分片会被丢弃。netstat -s -p ip 可以看到各项计数。</p>')],
    steps,
    [ENV_W + '。第一节在 en0 上抓包(用 tcpdump 的 pcap 文件交给 dpkt 解析),网关地址与 MAC 做了遮盖;第三节的丢包由 netlab 在 lo0 上注入,以太网分片数下的送达率是公式与随机模拟的结果,不是实测;第四节只测了一次 1 MiB 下载',
     '没有验证:IPv6(中间路由器不分片,只有源端分片)的行为;重组超时的具体时长与触发;分片重叠 / 微小分片攻击;分片对防火墙、NAT 的影响;真实以太网路径上的丢包下分片数据报的送达率;netstat 里“收到的分片 1716 而成功重组 0”的原因'],
    'IP 分片')
